s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";i:1;s:8:\"keywords\";a:0:{}}s:14:\"original_image\";s:12:\"HWBSH-1.jpeg\";}'),(958,677,'_oum_location_image','/wp-content/uploads/2025/10/HWBSH-1-rotated.jpeg|/wp-content/uploads/2025/10/409452803_734364068740482_7266895163952772940_n-768x1024.jpg|/wp-content/uploads/2025/10/409181905_733897062120516_5656952904419954301_n-768x512.jpg'),(959,677,'_thumbnail_id','679'),(960,677,'_oum_location_key','a:8:{s:7:\"address\";s:0:\"\";s:3:\"lat\";d:-35.9128307;s:3:\"lng\";d:150.0777465;s:4:\"text\";s:1261:\"The Red Door Hall in Moruya has been fitted with air-conditioning, a HEPA filter (air purifier), backup generator, solar panels, solar battery, two water tanks which hold 10kL each, and a fire hose with pump. When the Bureau of Meteorology declares severe or extreme heatwaves of more than 3 days’ duration, the haven will be open from 10am to 7pm, and can hold up to 50 people during the day. Flags will be displayed out the front when the haven is open for business. During a natural disaster, the haven can accommodate up to 26 people overnight in 6 camp beds with the rest sleeping on pews and on the floor.  <br><br>The facilities available to host visitors comfortably include:  <br><br>- men\\\'s and women\\\'s toilets (2 cubicles in each) <br><br>- kitchen facilities<br><br>- projector and screen <br><br>- Starlink wifi.  <br><br>There is a wheelchair ramp to access the hall. The haven can take pets and while there is no shelter for livestock, they can be held on the grounds.  <br><br>Located at 15B Page St Moruya, the Red Door Hall heatwave and bushfire smoke haven is open to the public, but is best suited to single adults who are vulnerable, elderly, live in suboptimal housing or have special needs which cannot be met in evacuation centres.  \";s:5:\"video\";s:0:\"\";s:12:\"notification\";s:0:\"\";s:11:\"author_name\";s:0:\"\";s:12:\"author_email\";s:0:\"\";}'),(961,677,'_oum_location_audio',''),(962,683,'_edit_lock','1761018450:1'),(963,683,'_edit_last','1'),(964,687,'_edit_lock','1762136358:1'),(965,687,'_edit_last','1'),(966,689,'_edit_lock','1762138712:1'),(967,689,'_edit_last','1'),(968,691,'_wp_attached_file','2025/10/SHASA-achievements-2019-2023.pdf'),(969,691,'_wp_attachment_metadata','a:2:{s:5:\"sizes\";a:4:{s:4:\"full\";a:5:{s:4:\"file\";s:36:\"SHASA-achievements-2019-2023-pdf.jpg\";s:5:\"width\";i:1497;s:6:\"height\";i:2117;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:595987;}s:6:\"medium\";a:5:{s:4:\"file\";s:44:\"SHASA-achievements-2019-2023-pdf-212x300.jpg\";s:5:\"width\";i:212;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:83090;}s:5:\"large\";a:5:{s:4:\"file\";s:45:\"SHASA-achievements-2019-2023-pdf-724x1024.jpg\";s:5:\"width\";i:724;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:220244;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:44:\"SHASA-achievements-2019-2023-pdf-106x150.jpg\";s:5:\"width\";i:106;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:70594;}}s:8:\"filesize\";i:492744;}'),(974,394,'_wp_page_template','wp-custom-template-newsletter'),(976,493,'_wp_page_template','default'),(977,398,'_wp_page_template','default'),(980,697,'is_wp_suggestion','1'),(981,703,'_menu_item_type','custom'),(982,703,'_menu_item_menu_item_parent','0'),(983,703,'_menu_item_object_id','703'),(984,703,'_menu_item_object','custom'),(985,703,'_menu_item_target',''),(986,703,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(987,703,'_menu_item_xfn',''),(988,703,'_menu_item_url','http://172.19.125.1:8080/'),(989,703,'_menu_item_orphaned','1760407472'),(990,704,'_menu_item_type','post_type'),(991,704,'_menu_item_menu_item_parent','0'),(992,704,'_menu_item_object_id','613'),(993,704,'_menu_item_object','page'),(994,704,'_menu_item_target',''),(995,704,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(996,704,'_menu