,'',0),(789,1,'2025-10-21 12:08:21','2025-10-21 01:08:21','<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/SHASA-Privacy-Policy.pdf\">Privacy policy</a> (pdf 399kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/Key-Performance-Indicators-2024.pdf\">Key Performance Indicators</a> (pdf 47kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/SHASA-CHILD-SAFE-POLICY-v-1.0.pdf\">Working with Children</a> (pdf 71kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/SHASA-Fundraising-Strategy.pdf\">Fundraising Strategy</a> (pdf 46kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/Succession-Planning-Policy.pdf\">Succession Planning</a> (pdf 47kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/SHASA-Resources-for-NFPs.pdf\">SHASA Resources</a> (many items are available for NFPs to borrow, pdf 50kb)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"https://shasa.com.au/wp-content/uploads/2024/12/SHASA-Position-Descriptions.pdf\">Position Description</a> (pdf 75kb)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>The following documents are available upon request. Please email <a href=\"mailto:contact.shasa@gmail.com\">contact.shasa@gmail.com</a>&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Risk Assessment Plan (by request)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Code of Conduct (by request)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Conflict of Interest (by request)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SHASA Finance Report (by request)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Funding for this page was provided by the FRRR Investing in Rural Communities Futures Program</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://ircf.frrr.org.au/\">https://ircf.frrr.org.au/</a></p>\n<!-- /wp:paragraph -->','Governance','','inherit','closed','closed','','786-revision-v1','','','2025-10-21 12:08:21','2025-10-21 01:08:21','',786,'http://172.19.125.1:8080/?p=789',0,'revision','',0),(790,1,'2025-10-21 12:08:22','2025-10-21 01:08:22','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:cover {\"url\":\"http://172.19.125.15:8080/wp-content/uploads/2025/09/banner-1024x427.png\",\"id\":163,\"dimRatio\":50,\"customOverlayColor\":\"#7f93b6\",\"isUserOverlayColor\":false,\"focalPoint\":{\"x\":0.17,\"y\":0.51},\"minHeight\":580,\"minHeightUnit\":\"px\",\"isDark\":false,\"sizeSlug\":\"large\",\"className\":\"no-margin\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light no-margin\" style=\"min-height:580px\"><img class=\"wp-block-cover__image-background wp-image-163 size-large\" alt=\"\" src=\"http://172.19.125.15:8080/wp-content/uploads/2025/09/banner-1024x427.png\" style=\"object-position:17% 51%\" data-object-fit=\"cover\" data-object-position=\"17% 51%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#7f93b6\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:site-logo {\"width\":219} /-->\n\n<!-- wp:heading {\"level\":1,\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"fontSize\":\"xx-large\",\"fontFamily\":\"commissioner\"} -->\n<h1 class=\"wp-block-heading is-style-default has-commissioner-font-family has-xx-large-font-size\" style=\"padding-right:0;padding-left:0\"><mark style=\"background-color:rgba(