r .25s ease;\\n  opacity: .0;\\n}\\n.hover-text:hover .wp-block-cover__background {\\n  opacity: .7;\\n}\\n\\n\\/* text reveal on hover *\\/\\n.hover-text .wp-block-cover__inner-container {\\n  transition: opacity .25s ease, transform .25s ease;\\n  opacity: 0;\\n  transform: translateY(8px);\\n}\\n.hover-text:hover .wp-block-cover__inner-container {\\n  opacity: 1;\\n  transform: translateY(0);\\n}\\n\\n\\/* keyboard accessibility: show text on focus *\\/\\n.hover-text:focus-within .wp-block-cover__inner-container {\\n  opacity: 1;\\n  transform: translateY(0);\\n}\\n\\n\\/* reduce motion preference *\\/\\n@media (prefers-reduced-motion: reduce) {\\n  .hover-text, .hover-text .wp-block-cover__background, .hover-text .wp-block-cover__inner-container {\\n    transition: none;\\n  }\\n}\\n\\n@media (max-width: 768px) {\\n  .responsive-column {\\n    display: grid !important;\\n    grid-template-columns: 1fr 1fr;\\n    gap: 1rem;\\n    font-size: 1rem;\\n  }\\n  \\/* Adjust text inside cover blocks *\\/\\n  .responsive-column .wp-block-cover p,\\n  .responsive-column .wp-block-cover .wp-block-cover__text {\\n    font-size: 0.9rem !important;\\n  }\\n}\",\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"300\",\"fontFamily\":\"var(--wp--preset--font-family--commissioner)\",\"fontSize\":\"var(--wp--preset--font-size--small)\"},\"spacing\":{\"padding\":{\"top\":\"0px\",\"right\":\"var(--wp--preset--spacing--40)\",\"bottom\":\"0px\",\"left\":\"var(--wp--preset--spacing--40)\"}}},\"settings\":{\"color\":{\"palette\":{\"theme\":[{\"color\":\"#FFFFFF\",\"name\":\"Base\",\"slug\":\"base\"},{\"color\":\"#111111\",\"name\":\"Contrast\",\"slug\":\"contrast\"},{\"color\":\"#2b61aa\",\"name\":\"Accent 1\",\"slug\":\"accent-1\"},{\"color\":\"#c0dafc\",\"name\":\"Accent 2\",\"slug\":\"accent-2\"},{\"color\":\"#1d3d68\",\"name\":\"Accent 3\",\"slug\":\"accent-3\"},{\"color\":\"#686868\",\"name\":\"Accent 4\",\"slug\":\"accent-4\"},{\"color\":\"#d1dae6\",\"name\":\"Accent 5\",\"