>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":455,\"mediaLink\":\"http://172.19.125.111:8080/?attachment_id=455\",\"mediaType\":\"image\",\"mediaWidth\":25,\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60);grid-template-columns:auto 25%\"><div class=\"wp-block-media-text__content\"><!-- wp:wpforms/form-selector {\"clientId\":\"a126e1b4-e03e-4c76-b9f1-a0d7f75c8d27\",\"formId\":\"440\",\"displayTitle\":true,\"theme\":\"default\",\"themeName\":\"Default\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:true,\\u0022displayDesc\\u0022:false,\\u0022theme\\u0022:\\u0022default\\u0022,\\u0022themeName\\u0022:\\u0022Default\\u0022,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022backgroundImage\\u0022:\\u0022none\\u0022,\\u0022backgroundPosition\\u0022:\\u0022center center\\u0022,\\u0022backgroundRepeat\\u0022:\\u0022no-repeat\\u0022,\\u0022backgroundSizeMode\\u0022:\\u0022cover\\u0022,\\u0022backgroundSize\\u0022:\\u0022cover\\u0022,\\u0022backgroundWidth\\u0022:\\u0022100px\\u0022,\\u0022backgroundHeight\\u0022:\\u0022100px\\u0022,\\u0022backgroundUrl\\u0022:\\u0022url()\\u0022,\\u0022backgroundColor\\u0022:\\u0022rgba( 0, 0, 0, 0 )\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBorderStyle\\u0022:\\u0022solid\\u0022,\\u0022fieldBorderSize\\u0022:\\u00221px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022fieldMenuColor\\u0022:\\u0022#ffffff\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022lab