v1','','','2025-11-03 13:04:52','2025-11-03 02:04:52','',1104,'http://172.19.125.139:8080/?p=1107',0,'revision','',0),(1108,1,'2025-08-03 13:05:58','2025-08-03 03:05:58','<!-- wp:file {\"id\":955,\"href\":\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\",\"displayPreview\":true} -->\n<div class=\"wp-block-file\"><object class=\"wp-block-file__embed\" data=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\" type=\"application/pdf\" style=\"width:100%;height:600px\" aria-label=\"July August 2025 newsletter\"></object><a id=\"wp-block-file--media-ea9fbf78-9542-43a9-a36b-22fc345e2169\" href=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\">July August 2025 newsletter</a><a href=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\" class=\"wp-block-file__button wp-element-button\" download aria-describedby=\"wp-block-file--media-ea9fbf78-9542-43a9-a36b-22fc345e2169\">Download</a></div>\n<!-- /wp:file -->','August Newsletter 2025','','publish','closed','closed','','august-newsletter-2025','','','2025-11-03 13:12:56','2025-11-03 02:12:56','',0,'http://172.19.125.139:8080/?p=1108',0,'post','',0),(1109,1,'2025-11-03 13:05:50','2025-11-03 02:05:50','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:cover {\"url\":\"http://172.19.125.1:8080/wp-content/uploads/2025/09/banner.png\",\"id\":163,\"dimRatio\":50,\"overlayColor\":\"contrast\",\"isUserOverlayColor\":true,\"minHeight\":302,\"minHeightUnit\":\"px\",\"sizeSlug\":\"full\",\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover aligncenter\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-bottom:0;min-height:302px\"><img class=\"wp-block-cover__image-background wp-image-163 size-full\" alt=\"\" src=\"http://172.19.125.1:8080/wp-content/uploads/2025/09/banner.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-contrast-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"left\",\"className\":\"is-style-default\",\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-left is-style-default has-xx-large-font-size\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-base-color\">Heat Haven</mark>s</h2>\n<!-- /wp:heading --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">In partnership with community organisations that run facilities, SHASA has undertaken upgrades on seven buildings so far:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Red Door Hall, Anglican Parish (solar, batteries, air conditioning, blinds, insulation, kitchen upgrade)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Moruya PreSchool Kindergarten (solar, batteries, backup generator, pump, fire hoses)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">CWA Moruya (solar, batteries, backup gas generator, air conditioning, HEPA filters, electrical upgrade, LED lighting and window shutters)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">CWA Narooma (new roof, insulation, solar, batteries, new flooring, kitchen upgrade, window shutters)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Uniting Church Catalina (solar, batteries, backup generators, HEPA filters, accessible toilet, washing machine, fridges, shelving, replacement of gas heaters with air conditioners)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Anglican Church Batemans Bay (electrical upgrade, LED lighting, solar, and batteries)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<li style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Moruya Surf Club (solar batteries, backup generator, LED lighting, air conditioning and filters)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">SHASA is currently seeking grant funding to upgrade the following buildings:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Southern Life Church Moruya</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Broulee Surf Club</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Anglican Parish Batemans Bay (Stage 3)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">SHASA believes it is time to update the strategy to a Community Resilience Strategy and add facilities that need just solar and batteries to reduce their electricity costs.&nbsp; If you know of a community building that may benefit from SHASA’s assistance, please send an email with details to&nbsp;<a href=\"mailto:contact.shasa@gmail.com\">contact.shasa@gmail.com</a>&nbsp;</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:open-user-map/map {\"size\":\"default\"} /-->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','page-heat-havens','','inherit','closed','closed','','697-revision-v1','','','2025-11-03 13:05:50','2025-11-03 02:05:50','',697,'http://172.19.125.139:8080/?p=1109',0,'revision','',0),(1110,1,'2025-11-03 13:05:58','2025-11-03 02:05:58','<!-- wp:file {\"id\":955,\"href\":\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\",\"displayPreview\":true} -->\n<div class=\"wp-block-file\"><object class=\"wp-block-file__embed\" data=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\" type=\"application/pdf\" style=\"width:100%;height:600px\" aria-label=\"July August 2025 newsletter\"></object><a id=\"wp-block-file--media-ea9fbf78-9542-43a9-a36b-22fc345e2169\" href=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\">July August 2025 newsletter</a><a href=\"http://172.19.125.139:8080/wp-content/uploads/2025/10/July-August-2025-newsletter-1.pdf\" class=\"wp-block-file__button wp-element-button\" download aria-describedby=\"wp-block-file--media-ea9fbf78-9542-43a9-a36b-22fc345e2169\">Download</a></div>\n<!-- /wp:file -->','August Newsletter 2025','','inherit','closed','closed','','1108-revision-v1','','','2025-11-03 13:05:58','2025-11-03 02:05:58','',1108,'http://172.19.125.139:8080/?p=1110',0,'revision','',0),(1111,1,'2025-11-03 13:06:10','2025-11-03 02:06:10','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:cover {\"url\":\"http://172.19.125.15:8080/wp-content/uploads/2025/09/banner-1024x427.png\",\"id\":163,\"dimRatio\":50,\"customOverlayColor\":\"#7f93b6\",\"isUserOverlayColor\":false,\"focalPoint\":{\"x\":0.17,\"y\":0.51},\"minHeight\":580,\"minHeightUnit\":\"px\",\"isDark\":false,\"sizeSlug\":\"large\",\"className\":\"no-margin\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light no-margin\" style=\"min-height:580px\"><img class=\"wp-block-cover__image-background wp-image-163 size-large\" alt=\"\" src=\"http://172.19.125.15:8080/wp-content/uploads/2025/09/banner-1024x427.png\" style=\"object-position:17% 51%\" data-object-fit=\"cover\" data-object-position=\"17% 51%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#7f93b6\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:site-logo {\"width\":219} /-->\n\n<!-- wp:heading {\"level\":1,\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"fontSize\":\"xx-large\",\"fontFamily\":\"commissioner\"} -->\n<h1 class=\"wp-block-heading is-style-default has-commissioner-font-family has-xx-large-font-size\" style=\"padding-right:0;padding-left:0\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-base-color\">Helping Make The </mark><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-base-color\">Eurobodalla </mark><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-base-color\">A Better Place To </mark><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-base-color\">Live, Work &amp; Play</mark></h1>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"accent-2\",\"textColor\":\"accent-1\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent-1\"}}},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-accent-1-color has-accent-2-background-color has-text-color has-background has-link-color wp-element-button\" href=\"/?page_id=590\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--40)\">Donate Now</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"className\":\"main-stack\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"0vw\",\"right\":\"0vw\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group main-stack\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:0vw;padding-bottom:var(--wp--preset--spacing--50);padding-left:0vw\"><!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column {\"width\":\"75%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:75%\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"376px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"flexWrap\":\"wrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:376px;margin-top:0;margin-bottom:0;padding-right:0;padding-left:0\"><!-- wp:heading {\"className\":\"is-style-default\"} -->\n<h2 class=\"wp-block-heading is-style-default\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-accent-1-color\">Southcoast Health &amp; Sustainability Alliance</mark></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Community-led solutions including</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\">Proactive responses to the&nbsp;climate crisis&nbsp;including drought, floods and bushfires</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\">Community&nbsp;solar and energy efficiency projects</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\">Community engagement, local food &amp; water security</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">The municipality of Eurobodalla covers 110km of the south coast between Durras and Wallaga Lake including Bateman’s Bay, Mogo, Moruya, Tuross Head, Narooma and many hamlets in between. With our recent experiences of drought, bushfires, floods and COVID 19, Eurobodalla has a great opportunity to<strong>&nbsp;reinvent</strong>&nbsp;itself.&nbsp;<strong>New technologies, new thinking, new living and new work opportunities</strong>&nbsp;can help us create an inspiring future for all as we move to a better, cleaner economy.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Check out our strategic plan&nbsp;<a href=\"https://shasa.com.au/wp-content/uploads/2024/11/SHASA2030-1124s.pdf\" target=\"_blank\" rel=\"noreferrer noopener\">SHASA’s 2030 Vision</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Our Aim:&nbsp;<strong>100% Renewable Energy Eurobodalla by 2030</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Acknowledgement of Country –&nbsp;<em>SHASA recognises Aboriginal people of the Yuin Nation as the original inhabitants and custodians of all land and water in the Eurobodalla and respects their enduring cultural and spiritual connection to it. SHASA acknowledges the Traditional Owners of the land in which we live and we pay our respect to Elders past, present and emerging.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-right:0;padding-left:0;flex-basis:25%\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:0px;margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"textAlign\":\"left\",\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} -->\n<h2 class=\"wp-block-heading has-text-align-left\">Recent News</h2>\n<!-- /wp:heading -->\n\n<!-- wp:rss {\"feedURL\":\"https://www.theguardian.com/environment/climate-crisis/rss\",\"itemsToShow\":4,\"displayAuthor\":true,\"displayDate\":true,\"className\":\"rss-feed\",\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent-3\"}}}},\"textColor\":\"contrast\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-left is-style-default\" style=\"margin-right:0;margin-left:0\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-accent-1-color\">Community Led Solutions</mark></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"isStackedOnMobile\":false,\"className\":\"responsive-column\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|40\"},\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\"}},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top is-not-stacked-on-mobile responsive-column\" style=\"padding-right:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"px\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:cover {\"url\":\"http://localhost:8080/wp-content/uploads/2025/10/HWBSH-1-rotated.jpeg\",\"id\":679,\"dimRatio\":50,\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"className\":\"hover-text\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"border\":{\"radius\":\"8px\"},\"dimensions\":{\"aspectRatio\":\"3/4\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-cover hover-text\" style=\"border-radius:8px;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><img class=\"wp-block-cover__image-background wp-image-679 size-full\" alt=\"\" src=\"http://localhost:8080/wp-content/uploads/2025/10/HWBSH-1-rotated.jpeg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"left\",\"placeholder\":\"Write title…\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-medium-font-size\">SHASA creates and maintains bushfire and heatwave heat havens for the community.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Heat Havens</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"px\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:cover {\"url\":\"http://localhost:8080/wp-content/uploads/2025/10/shasa_solar-scaled.jpg\",\"id\":979,\"dimRatio\":50,\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"className\":\"hover-text\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"border\":{\"radius\":\"8px\"},\"dimensions\":{\"aspectRatio\":\"3/4\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-cover hover-text\" style=\"border-radius:8px;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><img class=\"wp-block-cover__image-background wp-image-979 size-full\" alt=\"\" src=\"http://localhost:8080/wp-content/uploads/2025/10/shasa_solar-scaled.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"left\",\"placeholder\":\"Write title…\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-medium-font-size\">SHASA joined forces with Micro Energy Systems Australia (MESA) to support these community not for profit organisations.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Community Solar Installations</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"px\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:cover {\"url\":\"http://localhost:8080/wp-content/uploads/2025/10/Maleny-EV-Chargers.webp\",\"id\":980,\"dimRatio\":50,\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"className\":\"hover-text\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"border\":{\"radius\":\"8px\"},\"dimensions\":{\"aspectRatio\":\"3/4\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-cover hover-text\" style=\"border-radius:8px;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><img class=\"wp-block-cover__image-background wp-image-980 size-full\" alt=\"\" src=\"http://localhost:8080/wp-content/uploads/2025/10/Maleny-EV-Chargers.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"left\",\"placeholder\":\"Write title…\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-medium-font-size\">SHASA has formed the Eurobodalla Battery Electric Vehicle Club (Euro BEV club) with a view to meet on a regular basis.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /w